fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    let mut result = Vec::with_capacity(a.len());
    
    for s in a {
        if s.is_empty() {
            // For empty strings, return a vector with one empty string
            result.push(vec![String::new()]);
        } else {
            // Split the string by lines
            let lines: Vec<String> = if keepends {
                // When keepends is true, include the line ending characters
                s.lines()
                    .map(|line| {
                        // Check if the line ends with a newline in the original string
                        let mut line_with_ending = line.to_string();
                        // Since lines() removes trailing newlines, we need to add them back
                        // when keepends is true and the line had a newline in the original
                        if keepends && s.ends_with('\n') && line == s.trim_end_matches('\n') {
                            line_with_ending.push('\n');
                        }
                        line_with_ending
                    })
                    .collect()
            } else {
                // When keepends is false, just split normally
                s.lines().map(String::from).collect()
            };
            
            // Ensure the inner list is non-empty
            if lines.is_empty() {
                result.push(vec![String::new()]);
            } else {
                result.push(lines);
            }
        }
    }
    
    result
}